CREATE OR REPLACE FUNCTION public.validar_assinatura_checkout_visita() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN IF (TG_OP = 'INSERT' AND NEW.checkout_em IS NOT NULL) OR (TG_OP = 'UPDATE' AND OLD.checkout_em IS NULL AND NEW.checkout_em IS NOT NULL) THEN IF NEW.assinatura_saida_path IS NULL OR btrim(NEW.assinatura_saida_path) = '' OR NEW.checkout_registrado_por IS NULL THEN RAISE EXCEPTION 'A assinatura do visitante e o técnico responsável são obrigatórios no check-out.'; END IF; END IF; IF TG_OP = 'UPDATE' AND OLD.assinatura_saida_path IS NOT NULL AND (NEW.assinatura_saida_path IS DISTINCT FROM OLD.assinatura_saida_path OR NEW.checkout_em IS DISTINCT FROM OLD.checkout_em OR NEW.checkout_registrado_por IS DISTINCT FROM OLD.checkout_registrado_por) THEN RAISE EXCEPTION 'Uma saída assinada não pode ser alterada.'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER validar_assinatura_checkout_visita BEFORE INSERT OR UPDATE ON public.visitas FOR EACH ROW EXECUTE FUNCTION public.validar_assinatura_checkout_visita();